pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempt = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= config.max_attempts => {
                return Err(error);
            }
            Err(error) => {
                sleeper.sleep_ms(delay);
                // Saturating multiplication prevents overflow for large attempt counts.
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
                let _ = error;
            }
        }
    }
}

